// Month index → index into EU_YEARS (most recent vintage at or before that
// month, -1 before the first) and into EU_QUARTERS. Computed once for the axis.
const YEAR_SLOT: number[] = IVI_MONTHS.map((ym) => {
  const y = Number(ym.slice(0, 4));
  let slot = -1;
  for (let i = 0; i < EU_YEARS.length; i++) if (EU_YEARS[i] <= y) slot = i;
  return slot;
});
const QUARTER_SLOT: number[] = IVI_MONTHS.map((ym) => {
  const q = `${ym.slice(0, 4)}-Q${Math.floor((Number(ym.slice(5, 7)) - 1) / 3) + 1}`;
  const i = EU_QUARTERS.indexOf(q);
  // Months past the last published quarter carry the final one forward.
  return i >= 0 ? i : q > (EU_QUARTERS[EU_QUARTERS.length - 1] || "") ? EU_QUARTERS.length - 1 : -1;
});

// Forward-filled rate per country: a quarter a country did not publish inherits
// the most recent one it did, so a reporting gap holds the level rather than
// dropping the country off the map for a quarter.
const RATE_FILLED: Record<string, number[]> = Object.fromEntries(
  Object.entries(EU_VACANCY_RATE).map(([c, arr]) => {
    let last = 0;
    return [c, arr.map((v) => (v > 0 ? (last = v) : last))];
  }),
);

// Employment → active vacancies, per country per month, at that country's own rate.
function expand(byCity: Record<string, number[]>): Record<string, number[]> {
  const out: Record<string, number[]> = {};
  for (const [city, emp] of Object.entries(byCity)) {
    const rate = RATE_FILLED[city] || [];
    out[city] = IVI_MONTHS.map((_ym, i) => {
      const yi = YEAR_SLOT[i];
      const qi = QUARTER_SLOT[i];
      if (yi < 0 || qi < 0) return 0;
      const e = emp[yi] || 0;
      const r = (rate[qi] || 0) / 100;
      if (e <= 0 || r <= 0 || r >= 1) return 0;
      return Math.round((e * r) / (1 - r));
    });
  }
  return out;
}

// Skill → country id → monthly vacancy history (aligned to IVI_MONTHS).
export const EU_SERIES: Record<string, Record<string, number[]>> =
  Object.fromEntries(Object.entries(EU_EMPLOYMENT).map(([s, e]) => [s, expand(e)]));

// Skill → latest-month country vacancy count (current heat map).
export const EU_SKILL_BY_CITY: Record<string, Record<string, number>> =
  Object.fromEntries(
    Object.entries(EU_SERIES).map(([s, byCity]) => [
      s,
      Object.fromEntries(Object.entries(byCity).map(([c, arr]) => [c, arr[arr.length - 1]])),
    ]),
  );
